\includegraphics[scale=0.92]{PT_Top2.pdf}
\includegraphics[scale=0.92]{Eta_Top2.pdf} }
\caption{$p_T$ (left) and $\eta$ (right) distributions of the four tops at the parton-level for a benchmark point, $M_{V_1} = 1.5 \TeV$ and $c_t=2.0$.}
\label{fig:parton}
